import { EntityId } from "../types/id"
import { AccountRepository } from "../repositories/accountRepo"

export class PaymentService {
  constructor(private repo: AccountRepository) {}
  async processTransfer(fromId: EntityId, toId: EntityId, amount: number): Promise<boolean> {
    const from = await this.repo.findById(fromId)
    const to = await this.repo.findById(toId)
    if (!from || !to || from.balance < amount) return false
    from.balance -= amount
    to.balance += amount
    await this.repo.save(from)
    await this.repo.save(to)
    return true
  }
}

```

